const repository = String(env.get('ESS_GITHUB_REPOSITORY') || flow.get('ess_github_repository') || '').trim();
if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repository)) {
    node.status({fill:'red', shape:'ring', text:'repository niet ingesteld'});
    node.warn('Stel ESS_GITHUB_REPOSITORY lokaal in als owner/repository.');
    return null;
}
msg.method = 'GET';
msg.url = 'https://api.github.com/repos/' + repository + '/commits/main';
msg.repository = repository;
msg.headers = {
    'Accept': 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28',
    'User-Agent': 'Smart-ESS-Home-Assistant'
};
return msg;

if (msg.statusCode !== 200 || !msg.payload || !msg.payload.sha) {
    node.status({fill: 'red', shape: 'ring', text: 'GitHub niet bereikbaar: ' + (msg.statusCode || 'geen status')});
    return [null, {payload: {title: 'ESS GitHub-controle mislukt', message: 'De laatste commit kon niet worden gelezen. HTTP-status: ' + (msg.statusCode || 'onbekend')}}];
}

const latest = msg.payload.sha;
const latestShort = latest.substring(0, 7);
const deployed = flow.get('ess_github_deployed_sha');
const previousSeen = flow.get('ess_github_latest_sha');
const commitMessage = (msg.payload.commit && msg.payload.commit.message) || 'Geen commitbericht';
const commitUrl = msg.payload.html_url || ('https://github.com/' + msg.repository);

flow.set('ess_github_latest_sha', latest);
flow.set('ess_github_latest_url', commitUrl);
flow.set('ess_github_latest_message', commitMessage);

if (!deployed) {
    flow.set('ess_github_deployed_sha', latest);
    node.status({fill: 'green', shape: 'dot', text: 'basis vastgelegd: ' + latestShort});
    return null;
}

if (latest === deployed) {
    node.status({fill: 'green', shape: 'dot', text: 'actueel: ' + latestShort});
    return null;
}

node.status({fill: 'yellow', shape: 'ring', text: 'update: ' + latestShort});
if (latest === previousSeen) {
    return null;
}

msg.payload = {
    title: 'Nieuwe ESS-configuratie beschikbaar',
    message: commitMessage + '\n\nCommit: ' + latestShort + '\n' + commitUrl
};
return [msg, null];

const latest = flow.get('ess_github_latest_sha');
if (!latest) {
    node.warn('Er is nog geen GitHub-commit opgehaald.');
    return null;
}
flow.set('ess_github_deployed_sha', latest);
node.status({fill: 'green', shape: 'dot', text: 'toegepast: ' + latest.substring(0, 7)});
msg.payload = {notification_id: 'ess_github_update'};
return msg;
